<?php

namespace App\Notifications;

use Illuminate\Auth\Notifications\VerifyEmail as LaravelVerifyEmail;
use Illuminate\Notifications\Messages\MailMessage;
use Illuminate\Support\Facades\URL;

class VerifyEmailNotification extends LaravelVerifyEmail
{
    public function toMail($notifiable): MailMessage
    {
        // Sign the canonical public origin even when registration/resend is
        // requested on www, or the notification is generated by a worker.
        // Clone to avoid changing URL generation for the rest of the request.
        $urls = clone URL::getFacadeRoot();
        $urls->forceRootUrl(config('app.url'));
        $urls->forceScheme(parse_url(config('app.url'), PHP_URL_SCHEME));

        $verificationUrl = $urls->temporarySignedRoute(
            'verification.verify',
            now()->addMinutes(60),
            ['id' => $notifiable->getKey(), 'hash' => sha1($notifiable->getEmailForVerification())]
        );

        return (new MailMessage)
            ->subject('Vérifiez votre adresse email - DalyTrac')
            ->view('emails.verify-email', [
                'userName' => $notifiable->name ?? $notifiable->email,
                'verificationUrl' => $verificationUrl,
            ]);
    }
}
